import {appendWeaponLore} from './lore.js';
import {CREW,compileTechnique,compileLoadoutTechnique} from './mako.js?v=5.16.0';
const make=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;};
export function characterScreen({world,assets,renderer,data,onCraft,onBack,onParty,onGrid}){
 const s=world.state,root=make('section','character-screen');root.setAttribute('aria-label','Character details');
 const tabs=make('nav','crew-tabs');tabs.setAttribute('aria-label','Recruited characters');root.append(tabs);const content=make('div','character-layout');root.append(content);
 function paint(id){content.replaceChildren();for(const b of tabs.children)b.setAttribute('aria-pressed',String(Number(b.dataset.id)===id));const h=s.heroes[id],c=CREW[id];const art=make('div','character-art');art.style.setProperty('--affinity',({earth:'#d4ae72',mend:'#9ee5c4',flame:'#ed9b6b',ward:'#e6d09b',tide:'#80cfdc',gale:'#b8e4bd',shade:'#c1a0e8'})[c.affinity]);art.append(make('small','eyebrow',s.party.includes(id)?'TRAVELLING CREW':'AT CAMP'));const portrait=make('canvas','hero-portrait');portrait.width=400;portrait.height=480;portrait.setAttribute('aria-label',h.name+' character art');const basic=id===0&&s.story&&!s.story.armor,b=basic?renderer.bounds.starter[0]:renderer.bounds.crew[id*8];if(b){const scale=Math.min(320/b.w,380/b.h);portrait.getContext('2d').drawImage(basic?assets.starter:assets.crew,b.x,b.y,b.w,b.h,(400-b.w*scale)/2,430-b.h*scale,b.w*scale,b.h*scale);}art.append(portrait,make('h3','hero-name',h.name),make('p','affinity',c.affinity+' affinity · Level '+h.level));content.append(art);
 const details=make('div','character-details');content.append(details);details.append(make('small','eyebrow','CONDITION & GROWTH'));function meter(label,value,max,cls){const row=make('div','vital '+cls);row.append(make('span','',label),make('strong','',Math.floor(value)+' / '+max));const bar=make('progress');bar.max=Math.max(1,max);bar.value=value;bar.setAttribute('aria-label',label);row.append(bar);details.append(row);}meter('Health',h.hp,h.maxHp,'health');meter('Focus',h.mp,h.maxMp,'focus');const next=65*h.level*h.level,prev=65*(h.level-1)**2;if(h.level<45)meter('Experience to level '+(h.level+1),Math.max(0,s.xp-prev),next-prev,'experience');else details.append(make('p','', 'Maximum level reached'));
 const stats=make('div','hero-stats');for(const [label,value] of [['Power',h.power],['Magic',h.magic],['Speed',c.speed+'×'],['Strain',Math.round(h.strain||0)]]){const tile=make('div');tile.append(make('small','',label),make('strong','',value));stats.append(tile);}details.append(stats,make('h4','','Equipment'));const armor=s.story?.armor;details.append(make('p','equipment-line',id===0&&!armor?'Work clothes · no field gear equipped':h.equipment?'Reinforced weapon & focus band':'Standard field gear'));if(h.gearPower||h.gearHP)details.append(make('p','muted','Gear bonuses · Power +'+(h.gearPower||0)+' · Health +'+(h.gearHP||0)));
 details.append(make('h4','','Linked techniques'));if(!h.loadout?.length)details.append(make('p','muted','No core patterns equipped. Continue the journey to discover crystal craft.'));for(const slot of h.loadout||[]){const t=compileLoadoutTechnique(slot,h,s),row=make('article','tech-card');row.style.borderLeftColor=t.color;row.append(make('strong','',t.name),make('small','',t.cost+' MP · Rank '+t.rank+' · '+(h.ap[slot.core]||0)+' AP'),make('p','muted',t.shape+' · '+slot.core+' / '+slot.support));details.append(row);}const learned=data.skills.characters[id].skills.filter((v,i)=>h.learned&(1<<(7-i)));details.append(make('h4','','Personal techniques'),make('p','muted',learned.length?learned.map(x=>x.name).join(' · '):'Personal techniques will awaken as the story unfolds.'));const actions=make('div','character-actions');for(const [label,fn]of [['Resonance paths',onGrid],['Crystal craft',onCraft],['Formation',onParty],['Back to pause',onBack]]){const b=make('button','',label);b.onclick=fn;actions.append(b);}details.append(actions);appendWeaponLore(details,h.name);}
 for(const id of s.recruited){const b=make('button','',CREW[id].name);b.dataset.id=id;b.onclick=()=>paint(id);tabs.append(b);}paint(s.party[0]);return root;
}
export function pauseOverview(world){const s=world.state,root=make('div','pause-overview');root.append(make('small','eyebrow','A MOMENT BETWEEN ADVENTURES'),make('h3','',world.scene.name||world.scene.title||'The journey continues'));const row=make('div','journey-totals');for(const [label,value]of [['Chapter',s.chapter],['Credits',s.gold],['Crew',s.recruited.length],['Keepsakes',s.exploration?.relics?.length||0]]){const d=make('div');d.append(make('strong','',value),make('small','',label));row.append(d);}root.append(row);return root;}
